package br.com.mathinclui.auth.security;
import org.junit.jupiter.api.Test; import java.time.*; import static org.assertj.core.api.Assertions.assertThat;
class LoginAttemptTrackerTest { @Test void shouldBlockAfterConfiguredNumberOfFailuresAndExpireBlock(){var clock=new MutableClock(Instant.parse("2026-10-15T18:00:00Z"));var tracker=new LoginAttemptTracker(3,Duration.ofMinutes(15),clock);tracker.recordFailure("student:127.0.0.1:joao");tracker.recordFailure("student:127.0.0.1:joao");assertThat(tracker.isBlocked("student:127.0.0.1:joao")).isFalse();tracker.recordFailure("student:127.0.0.1:joao");assertThat(tracker.isBlocked("student:127.0.0.1:joao")).isTrue();clock.advance(Duration.ofMinutes(16));assertThat(tracker.isBlocked("student:127.0.0.1:joao")).isFalse();} @Test void shouldClearFailuresAfterSuccessfulLogin(){var tracker=new LoginAttemptTracker(2,Duration.ofMinutes(15),Clock.systemUTC());tracker.recordFailure("teacher:ip:email");tracker.recordSuccess("teacher:ip:email");tracker.recordFailure("teacher:ip:email");assertThat(tracker.isBlocked("teacher:ip:email")).isFalse();} private static final class MutableClock extends Clock{private Instant instant;private MutableClock(Instant instant){this.instant=instant;}void advance(Duration duration){instant=instant.plus(duration);}@Override public ZoneId getZone(){return ZoneId.of("UTC");}@Override public Clock withZone(ZoneId zone){return this;}@Override public Instant instant(){return instant;}} }
